   if(part==2){opaque=!company&&g.material!=NativeDoorGlass.ORIGINAL&&GlassRenderPolicy.opaque(g.tint);if(company)quads=NativeDoorMaterials.companyGlass(quads,new ProgrammableModel.MaterialSnapshot(sprite("vandorlabs:door-artwork/blocks/space_doors/low/glass_tile"),1,1));else if(g.material!=NativeDoorGlass.ORIGINAL){ProgrammableModel.MaterialSnapshot target;if(g.material<0){String name=com.vandorlabs.tiles.GlassTextures.texture(g.shade,1,g.tint).substring("vandorlabs:blocks/programmable_glass/low/".length());target=new ProgrammableModel.MaterialSnapshot(sprite("vandorlabs:glass-palette/"+name),1,1);}else target=material(g.material,false);quads=NativeDoorMaterials.glass(quads,settings,scale,target);}}
   else if(part==1&&settings.faceTexture()>=0)quads=NativeDoorMaterials.face(quads,settings,material(settings.faceTexture(),true),mirror,scale);
   else quads=NativeDoorMaterials.frame(quads,source.particle,settings,part,scale,materials);
